import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Mail,
  Building2,
  Globe,
  MessageSquare,
  Calendar,
  Trash2,
  Eye,
  CheckCircle2,
  Inbox,
  Filter,
  Search,
  Package,
  AlertCircle,
  User,
  Send,
  RefreshCw,
  XCircle,
  Clock,
  Shield,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { useInquiries, type IInquiry, type EmailStatus } from '@/hooks/useInquiries';
import { useEmailSettings } from '@/hooks/useEmailSettings';
import { format } from 'date-fns';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';

const EMAIL_STATUS_CLASSNAMES: Record<EmailStatus, { className: string; icon: typeof Mail }> = {
  unsent: { className: 'bg-muted/50 text-muted-foreground border-border/50', icon: Clock },
  sending: { className: 'bg-info/15 text-info border-info/30', icon: RefreshCw },
  sent: { className: 'bg-success/15 text-success border-success/30', icon: CheckCircle2 },
  failed: { className: 'bg-destructive/15 text-destructive border-destructive/30', icon: XCircle },
};

const STATUS_CLASSNAMES: Record<IInquiry['status'], { className: string }> = {
  unread: { className: 'bg-destructive/15 text-destructive border-destructive/30' },
  read: { className: 'bg-info/15 text-info border-info/30' },
  replied: { className: 'bg-success/15 text-success border-success/30' },
};

export default function AdminInquiriesPage() {
  const { adminT } = useI18n();
  const { inquiries, updateStatus, deleteInquiry, clearAll, unreadCount, totalCount, buildMailto, notifyEmail, sendInquiryEmail } = useInquiries();
  const { settings: emailSettings, isConfigured: emailConfigured } = useEmailSettings();
  const [keyword, setKeyword] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [selected, setSelected] = useState<IInquiry | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [clearConfirmOpen, setClearConfirmOpen] = useState(false);
  const [resendingId, setResendingId] = useState<string | null>(null);

  const statusLabels = useMemo(() => ({
    unread: adminT('admin.inquiryStatusUnread'),
    read: adminT('admin.inquiryStatusRead'),
    replied: adminT('admin.inquiryStatusReplied'),
  }), [adminT]);

  const sourceLabels = useMemo(() => ({
    home: adminT('admin.inquirySourceHome'),
    contact: adminT('admin.inquirySourceContact'),
    product: adminT('admin.inquirySourceProduct'),
  }), [adminT]);

  const emailStatusLabels = useMemo(() => ({
    unsent: adminT('admin.emailStatusUnsent'),
    sending: adminT('admin.emailStatusSending'),
    sent: adminT('admin.emailStatusSent'),
    failed: adminT('admin.emailStatusFailed'),
  }), [adminT]);

  const filtered = useMemo(() => {
    return inquiries.filter((i) => {
      if (statusFilter !== 'all' && i.status !== statusFilter) return false;
      if (keyword) {
        const kw = keyword.toLowerCase();
        return (
          i.name?.toLowerCase().includes(kw) ||
          i.company.toLowerCase().includes(kw) ||
          i.email.toLowerCase().includes(kw) ||
          i.country.toLowerCase().includes(kw) ||
          i.message.toLowerCase().includes(kw)
        );
      }
      return true;
    });
  }, [inquiries, keyword, statusFilter]);

  const openDetail = (inquiry: IInquiry) => {
    setSelected(inquiry);
    setDetailOpen(true);
    if (inquiry.status === 'unread') {
      updateStatus(inquiry.id, 'read');
    }
  };

  const handleMarkReplied = (id: string) => {
    updateStatus(id, 'replied');
    toast.success(adminT('admin.inquiryMarkedReplied'));
  };

  const handleDelete = (id: string) => {
    deleteInquiry(id);
    setDeleteId(null);
    if (selected?.id === id) {
      setDetailOpen(false);
      setSelected(null);
    }
    toast.success(adminT('admin.inquiryDeleted'));
  };

  const handleClearAll = () => {
    clearAll();
    setClearConfirmOpen(false);
    setDetailOpen(false);
    setSelected(null);
    toast.success(adminT('admin.inquiryCleared'));
  };

  const handleResendEmail = async (inquiry: IInquiry) => {
    if (!emailConfigured) {
      toast.error(adminT('admin.inquiryEmailNotConfigured'));
      return;
    }
    setResendingId(inquiry.id);
    const ok = await sendInquiryEmail(inquiry, emailSettings.endpoint, emailSettings.recipientEmail);
    setResendingId(null);
    if (ok) {
      toast.success(adminT('admin.inquiryEmailResent'));
      // 刷新 selected 状态
      setSelected((prev) => prev && prev.id === inquiry.id ? { ...prev, emailStatus: 'sent' } : prev);
    } else {
      toast.error(adminT('admin.inquiryEmailFailed'));
    }
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.inquiries') }]}
      />
      {/* 隐私说明 */}
      <div className="flex items-start gap-3 p-4 rounded-sm border border-destructive/30 bg-destructive/5">
        <Shield className="size-5 text-destructive shrink-0 mt-0.5" />
        <div className="text-sm space-y-1">
          <p className="font-medium text-destructive">Privacy Notice</p>
          <p className="text-muted-foreground">
            Inquiry data is <strong>stored only in your local browser</strong> (localStorage) and will <strong>never</strong> be synced to GitHub — this protects customer privacy and keeps contact information out of public repositories.
          </p>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">{adminT('admin.inquiryTitle')}</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {adminT('admin.inquiryDesc')}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Badge variant="outline" className="bg-primary/10 text-primary border-primary/30">
            {adminT('admin.inquiryUnreadCount').replace('{count}', String(unreadCount))}
          </Badge>
          <Badge variant="outline" className="bg-muted/50">
            {adminT('admin.inquiryTotalCount').replace('{count}', String(totalCount))}
          </Badge>
          {totalCount > 0 && (
            <Button
              variant="outline"
              size="sm"
              className="text-destructive hover:text-destructive hover:bg-destructive/10 border-destructive/30"
              onClick={() => setClearConfirmOpen(true)}
            >
              <Trash2 className="size-4 mr-1.5" />
              {adminT('admin.inquiryClearAll')}
            </Button>
          )}
        </div>
      </div>

      {/* 筛选栏 */}
      <Card className="border-border/40 bg-card">
        <CardContent className="p-4">
          <div className="flex flex-col sm:flex-row gap-3">
            <div className="relative flex-1">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                type="search"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder={adminT('admin.inquirySearchPh')}
                className="pl-9 bg-background/60"
              />
            </div>
            <div className="flex items-center gap-2">
              <Filter className="size-4 text-muted-foreground shrink-0" />
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-36 bg-background/60">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">{adminT('admin.inquiryAllStatus')}</SelectItem>
                  <SelectItem value="unread">{statusLabels.unread}</SelectItem>
                  <SelectItem value="read">{statusLabels.read}</SelectItem>
                  <SelectItem value="replied">{statusLabels.replied}</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 询盘列表 */}
      {filtered.length === 0 ? (
        <Card className="border-border/40 bg-card">
          <CardContent className="p-12 flex flex-col items-center justify-center text-center">
            <div className="size-16 rounded-full bg-muted/30 flex items-center justify-center mb-4">
              <Inbox className="size-8 text-muted-foreground" />
            </div>
            <h3 className="text-base font-semibold text-foreground mb-1">{adminT('admin.inquiryEmpty')}</h3>
            <p className="text-sm text-muted-foreground">
              {totalCount === 0
                ? adminT('admin.inquiryEmptyDesc')
                : adminT('admin.inquiryFilteredEmpty')}
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          <AnimatePresence mode="popLayout">
            {filtered.map((inquiry) => (
              <motion.div
                key={inquiry.id}
                layout
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, height: 0 }}
                transition={{ duration: 0.2 }}
              >
                <Card
                  className={`border-border/40 bg-card cursor-pointer hover:border-primary/40 transition-colors ${
                    inquiry.status === 'unread' ? 'border-l-2 border-l-primary' : ''
                  }`}
                  onClick={() => openDetail(inquiry)}
                >
                  <CardContent className="p-4">
                    <div className="flex items-start gap-4">
                      <div className="size-10 shrink-0 rounded-lg bg-primary/10 flex items-center justify-center">
                        {inquiry.status === 'unread' ? (
                          <AlertCircle className="size-5 text-primary" />
                        ) : (
                          <Mail className="size-5 text-primary" />
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1 flex-wrap">
                          <span className="font-medium text-foreground truncate">
                            {inquiry.name || inquiry.company || adminT('admin.inquiryNotFilled')}
                          </span>
                          {inquiry.company && inquiry.name && (
                            <span className="text-xs text-muted-foreground truncate">
                              · {inquiry.company}
                            </span>
                          )}
                          <Badge
                            variant="outline"
                            className={`text-[10px] px-1.5 py-0 ${STATUS_CLASSNAMES[inquiry.status].className}`}
                          >
                            {statusLabels[inquiry.status]}
                          </Badge>
                          <Badge variant="outline" className="text-[10px] px-1.5 py-0">
                            {sourceLabels[inquiry.source]}
                          </Badge>
                          <Badge
                            variant="outline"
                            className={`text-[10px] px-1.5 py-0 ${EMAIL_STATUS_CLASSNAMES[inquiry.emailStatus || 'unsent'].className}`}
                          >
                            {emailStatusLabels[inquiry.emailStatus || 'unsent']}
                          </Badge>
                        </div>
                        <div className="flex items-center gap-4 text-xs text-muted-foreground flex-wrap">
                          <span className="inline-flex items-center gap-1">
                            <Mail className="size-3" />
                            {inquiry.email}
                          </span>
                          {inquiry.country && (
                            <span className="inline-flex items-center gap-1">
                              <Globe className="size-3" />
                              {inquiry.country}
                            </span>
                          )}
                          {inquiry.productName && inquiry.product !== 'all' && (
                            <span className="inline-flex items-center gap-1">
                              <Package className="size-3" />
                              {inquiry.productName}
                            </span>
                          )}
                          <span className="inline-flex items-center gap-1">
                            <Calendar className="size-3" />
                            {format(inquiry.createdAt, 'yyyy-MM-dd HH:mm')}
                          </span>
                        </div>
                        {inquiry.message && (
                          <p className="text-sm text-muted-foreground mt-2 line-clamp-1">
                            {inquiry.message}
                          </p>
                        )}
                      </div>
                      <div className="flex items-center gap-1 shrink-0" onClick={(e) => e.stopPropagation()}>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="size-8"
                          onClick={() => openDetail(inquiry)}
                          aria-label={adminT('admin.inquiryViewDetail')}
                        >
                          <Eye className="size-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="size-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                          onClick={() => setDeleteId(inquiry.id)}
                          aria-label={adminT('admin.inquiryDelete')}
                        >
                          <Trash2 className="size-4" />
                        </Button>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {/* 详情弹窗 */}
      <Dialog open={detailOpen} onOpenChange={setDetailOpen}>
        <DialogContent className="sm:max-w-xl max-h-[85vh] overflow-y-auto">
          {selected && (
            <>
               <DialogHeader>
                  <DialogTitle className="flex items-center gap-2">
                    <User className="size-5 text-primary" />
                    {selected.name || selected.company || adminT('admin.inquiryNotFilled')}
                    <div className="ml-auto flex items-center gap-1.5">
                      <Badge
                        variant="outline"
                        className={`text-[10px] ${EMAIL_STATUS_CLASSNAMES[selected.emailStatus || 'unsent'].className}`}
                      >
                        {emailStatusLabels[selected.emailStatus || 'unsent']}
                      </Badge>
                      <Badge
                        variant="outline"
                        className={`text-[10px] ${STATUS_CLASSNAMES[selected.status].className}`}
                      >
                        {statusLabels[selected.status]}
                      </Badge>
                    </div>
                  </DialogTitle>
                 <DialogDescription>
                   <span className="inline-flex items-center gap-1">
                     <Calendar className="size-3" />
                     {format(selected.createdAt, 'yyyy-MM-dd HH:mm')}
                   </span>
                   <span className="mx-2">·</span>
                    {adminT('admin.inquirySource')}: {sourceLabels[selected.source]}
                 </DialogDescription>
               </DialogHeader>

               <div className="space-y-4 py-2">
                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                   <div>
                      <label className="text-xs text-muted-foreground mb-1 block">{adminT('admin.inquiryName')}</label>
                     <div className="text-sm text-foreground flex items-center gap-1.5">
                       <User className="size-3.5 shrink-0 text-primary" />
                       {selected.name || '-'}
                     </div>
                   </div>
                   <div>
                      <label className="text-xs text-muted-foreground mb-1 block">{adminT('admin.inquiryCompany')}</label>
                     <div className="text-sm text-foreground flex items-center gap-1.5">
                       <Building2 className="size-3.5 shrink-0 text-primary" />
                       {selected.company || '-'}
                     </div>
                   </div>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                   <div>
                      <label className="text-xs text-muted-foreground mb-1 block">{adminT('admin.inquiryEmail')}</label>
                     <div className="text-sm text-foreground break-all flex items-center gap-1.5">
                       <Mail className="size-3.5 shrink-0 text-primary" />
                       {selected.email}
                     </div>
                   </div>
                   <div>
                      <label className="text-xs text-muted-foreground mb-1 block">{adminT('admin.inquiryCountry')}</label>
                     <div className="text-sm text-foreground flex items-center gap-1.5">
                       <Globe className="size-3.5 shrink-0 text-primary" />
                       {selected.country || '-'}
                     </div>
                   </div>
                 </div>

                <div>
                  <label className="text-xs text-muted-foreground mb-1 block">{adminT('admin.inquiryInterest')}</label>
                  <div className="text-sm text-foreground flex items-center gap-1.5">
                    <Package className="size-3.5 shrink-0 text-primary" />
                    {selected.productName && selected.product !== 'all'
                      ? selected.productName
                      : adminT('admin.allProducts')}
                  </div>
                </div>

                 {selected.emailStatus === 'failed' && selected.emailError && (
                   <div className="text-xs text-destructive bg-destructive/10 border border-destructive/30 rounded-md p-2">
                      {adminT('admin.inquirySendFailedReason')}{selected.emailError}
                   </div>
                 )}

                 <div>
                    <label className="text-xs text-muted-foreground mb-1 block">{adminT('admin.inquiryMessage')}</label>
                   <div className="text-sm text-foreground bg-muted/30 border border-border/40 rounded-md p-3 whitespace-pre-wrap min-h-[100px]">
                     {selected.message || adminT('admin.inquiryMessageNotFilled')}
                  </div>
                </div>
              </div>

              <DialogFooter className="flex-col sm:flex-row gap-2">
                <Button
                  variant="outline"
                  onClick={() => setDetailOpen(false)}
                >
                  {adminT('admin.inquiryClose')}
                </Button>
                <Button
                  variant="outline"
                  onClick={async () => {
                    await handleResendEmail(selected);
                  }}
                  disabled={resendingId === selected.id}
                >
                  {resendingId === selected.id ? (
                    <RefreshCw className="size-4 mr-1.5 animate-spin" />
                  ) : (
                    <RefreshCw className="size-4 mr-1.5" />
                  )}
                  {adminT('admin.inquiryResendEmail')}
                </Button>
                <Button
                  variant="outline"
                  onClick={() => {
                    const link = document.createElement('a');
                    link.href = buildMailto(selected);
                    link.rel = 'noopener noreferrer';
                    document.body.appendChild(link);
                    link.click();
                    document.body.removeChild(link);
                  }}
                >
                  <Send className="size-4 mr-1.5" />
                  {adminT('admin.inquirySendEmail')}
                </Button>
                {selected.status !== 'replied' && (
                  <Button
                    onClick={() => handleMarkReplied(selected.id)}
                    className="bg-success/20 text-success hover:bg-success/30 border border-success/30"
                    variant="outline"
                  >
                    <CheckCircle2 className="size-4 mr-1.5" />
                    {adminT('admin.inquiryMarkReplied')}
                  </Button>
                )}
                <Button
                  variant="outline"
                  className="text-destructive hover:text-destructive hover:bg-destructive/10 border-destructive/30"
                  onClick={() => {
                    setDetailOpen(false);
                    setDeleteId(selected.id);
                  }}
                >
                  <Trash2 className="size-4 mr-1.5" />
                  {adminT('admin.inquiryDelete')}
                </Button>
              </DialogFooter>
            </>
          )}
        </DialogContent>
      </Dialog>

      {/* 删除确认 */}
      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{adminT('admin.inquiryDeleteConfirm')}</AlertDialogTitle>
            <AlertDialogDescription>
              {adminT('admin.inquiryDeleteConfirmDesc')}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{adminT('admin.inquiryCancel')}</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
              onClick={() => deleteId && handleDelete(deleteId)}
            >
              {adminT('admin.inquiryConfirmDelete')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* 清空确认 */}
      <AlertDialog open={clearConfirmOpen} onOpenChange={setClearConfirmOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{adminT('admin.inquiryClearConfirm')}</AlertDialogTitle>
            <AlertDialogDescription>
              {adminT('admin.inquiryClearConfirmDesc').replace('{count}', String(totalCount))}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{adminT('admin.inquiryCancel')}</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
              onClick={handleClearAll}
            >
              {adminT('admin.inquiryConfirmClear')}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
